import { SURFACE_MATERIALS, type SurfaceMaterialId } from "./surfaceMaterials";

/**
 * The patterns of the 3D model (brick, boards, ashlar, roof tiles, grass), as plain pixels. They
 * are generated by code, so the project ships no image files. Kept apart from three.js: the 3D
 * engine turns them into textures, and the materials library draws its swatches from the very same
 * pixels without loading the engine.
 */

interface Texel {
    /** Multiplies the base colour; 1 leaves it as it is. */
    tone: number;
    /** Height for the relief, from 0 (deep) to 1 (raised). */
    height: number;
    /** A colour of its own, for what is not the base material, such as the mortar. */
    color?: number;
}

const SIZE = 256;
export const PATTERN_SIZE = SIZE;
const MORTAR_COLOR = 0xc4bcae;
const JOINT_COLOR = 0x3a2c22;

/** Repeatable noise: the same texel always gets the same value. */
function hash(x: number, y: number): number {
    const value = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;

    return value - Math.floor(value);
}

/** Smooth noise that tiles: values on a lattice of `cells` per side, blended in between. */
function cloud(x: number, y: number, cells: number): number {
    const fx = (x / SIZE) * cells;
    const fy = (y / SIZE) * cells;
    const x0 = Math.floor(fx);
    const y0 = Math.floor(fy);
    const tx = fx - x0;
    const ty = fy - y0;
    const at = (ix: number, iy: number) => hash(ix % cells, iy % cells);
    const sx = tx * tx * (3 - 2 * tx);
    const sy = ty * ty * (3 - 2 * ty);
    const top = at(x0, y0) + (at(x0 + 1, y0) - at(x0, y0)) * sx;
    const bottom = at(x0, y0 + 1) + (at(x0 + 1, y0 + 1) - at(x0, y0 + 1)) * sx;

    return top + (bottom - top) * sy;
}

/** The pixels of a pattern: RGBA colour and RGBA height, `PATTERN_SIZE` texels a side. */
export interface PatternPixels {
    colors: Uint8Array;
    heights: Uint8Array;
    /** Metres one tile covers on a surface. */
    tileM: number;
}

function build(base: number, tileM: number, texel: (x: number, y: number) => Texel): PatternPixels {
    const colors = new Uint8Array(SIZE * SIZE * 4);
    const heights = new Uint8Array(SIZE * SIZE * 4);

    for (let y = 0; y < SIZE; y += 1) {
        for (let x = 0; x < SIZE; x += 1) {
            const { tone, height, color = base } = texel(x, y);
            const offset = (y * SIZE + x) * 4;

            colors[offset] = Math.min(255, ((color >> 16) & 255) * tone);
            colors[offset + 1] = Math.min(255, ((color >> 8) & 255) * tone);
            colors[offset + 2] = Math.min(255, (color & 255) * tone);
            colors[offset + 3] = 255;
            heights.fill(Math.min(255, 255 * height), offset, offset + 3);
            heights[offset + 3] = 255;
        }
    }

    return { colors, heights, tileM };
}

/** Running bond: four bricks by eight courses per tile, every other course shifted half a brick. */
export function brickPixels(base: number): PatternPixels {
    const width = SIZE / 4;
    const height = SIZE / 8;

    return build(base, 0.84, (x, y) => {
        const course = Math.floor(y / height);
        const shifted = x + (course % 2 === 0 ? 0 : width / 2);

        if (shifted % width < 3 || y % height < 3) {
            return { tone: 0.9 + 0.1 * hash(x, y), height: 0.15, color: MORTAR_COLOR };
        }

        const tone = 0.78 + 0.32 * hash(Math.floor(shifted / width) % 4, course);

        return { tone: tone + 0.06 * (hash(x, y) - 0.5), height: 0.75 + 0.2 * hash(x, y) };
    });
}

/** Horizontal boards with their own tone, a dark joint between them and a faint vein. */
export function woodPixels(base: number): PatternPixels {
    const board = SIZE / 5;

    return build(base, 1, (x, y) => {
        const row = Math.floor(y / board);

        if (y % board < 2) {
            return { tone: 1, height: 0, color: JOINT_COLOR };
        }

        const vein = Math.sin((x / SIZE) * Math.PI * 2 * (3 + row) + hash(row, 3) * 6);

        return {
            tone: 0.84 + 0.24 * hash(1, row) + 0.05 * vein,
            height: 0.8 + 0.1 * vein,
        };
    });
}

/** Ashlar: four courses of blocks whose joints do not line up from one course to the next. */
export function stonePixels(base: number): PatternPixels {
    const course = SIZE / 4;
    const block = SIZE / 2;

    return build(base, 1.6, (x, y) => {
        const row = Math.floor(y / course);
        const shifted = x + Math.floor(hash(row, 7) * block);

        if (shifted % block < 3 || y % course < 3) {
            return { tone: 0.62, height: 0.1 };
        }

        const tone = 0.8 + 0.28 * hash(Math.floor(shifted / block) % 2, row);

        return {
            tone: tone + 0.1 * (cloud(x, y, 16) - 0.5),
            height: 0.6 + 0.4 * cloud(x, y, 16),
        };
    });
}

/** Courses of tiles: each one darkens towards the tile above it, which overlaps it. */
export function tilesPixels(base: number): PatternPixels {
    const course = SIZE / 6;
    const tile = SIZE / 8;

    return build(base, 1.2, (x, y) => {
        const row = Math.floor(y / course);
        const down = (y % course) / course;
        const shifted = x + (row % 2 === 0 ? 0 : tile / 2);

        if (shifted % tile < 1.5) {
            return { tone: 0.6, height: down * 0.5 };
        }

        const tone = 0.74 + 0.34 * down + 0.12 * (hash(Math.floor(shifted / tile) % 8, row) - 0.5);

        return { tone, height: down };
    });
}

/** Grass: two sizes of soft patches, never a flat green. */
export function grassPixels(base: number): PatternPixels {
    return build(base, 4, (x, y) => {
        const patch = 0.6 * cloud(x, y, 6) + 0.4 * cloud(x, y, 24);

        return { tone: 0.78 + 0.4 * patch + 0.08 * (hash(x, y) - 0.5), height: patch };
    });
}

/** The surfaces drawn with a pattern instead of a flat colour, and how to make it. */
export const SURFACE_PATTERNS: Partial<Record<SurfaceMaterialId, () => PatternPixels>> = {
    brick: () => brickPixels(SURFACE_MATERIALS.brick.color),
    wood: () => woodPixels(SURFACE_MATERIALS.wood.color),
    stone: () => stonePixels(SURFACE_MATERIALS.stone.color),
};
